    def _load_certificate(self):
        try:
            cert_data = self.cert_text.replace('-----BEGIN CERTIFICATE-----', '')
            cert_data = cert_data.replace('-----END CERTIFICATE-----', '')
            cert_data = cert_data.replace('\n', '').replace('\r', '')
