        return True

    def _find_response_signature(self):
        try:
            response_nodes = self.document.xpath(
                '//samlp:Response',
                namespaces=self.NAMESPACES
            )

            if not response_nodes:
                return None

            response = response_nodes[0]

            signature_nodes = response.xpath(
                './ds:Signature',
                namespaces=self.NAMESPACES
            )

            if signature_nodes:
                return signature_nodes[0]

            return None
